class SegmentTree {
public:
    int n;
    vector<int> tree;
    SegmentTree(int size) : n(size), tree(4 * size, -1) {}

    void update(int node, int l, int r, int idx, int val) {
        if (l == r) { tree[node] = val; return; }
        int mid = (l + r) / 2;
        if (idx <= mid) update(2 * node, l, mid, idx, val);
        else update(2 * node + 1, mid + 1, r, idx, val);
        tree[node] = max(tree[2 * node], tree[2 * node + 1]);
    }

    int query(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) return tree[node];
        if (r < ql || l > qr) return -1;
        int mid = (l + r) / 2;
        return max(query(2 * node, l, mid, ql, qr), query(2 * node + 1, mid + 1, r, ql, qr));
    }
};

class Solution {
public:
    long long maxRectangleArea(vector<int>& xCoord, vector<int>& yCoord) {
        int n = xCoord.size();
        vector<pair<int, int>> points(n);
        for (int i = 0; i < n; ++i) points[i] = {xCoord[i], yCoord[i]};
        sort(points.begin(), points.end());

        vector<int> ys = yCoord;
        sort(ys.begin(), ys.end());
        ys.erase(unique(ys.begin(), ys.end()), ys.end());
        unordered_map<int, int> yToIdx;
        for (size_t i = 0; i < ys.size(); ++i) yToIdx[ys[i]] = i;

        SegmentTree st(ys.size());
        unordered_map<int, int> lastX;
        long long ans = -1;

        size_t i = 0;
        while (i < points.size()) {
            size_t j = i;
            while (j < points.size() && points[j].first == points[i].first) j++;
            for (size_t k = i; k + 1 < j; ++k) {
                int x = points[k].first;
                int y1 = points[k].second;
                int y2 = points[k + 1].second;
                int idx1 = yToIdx[y1], idx2 = yToIdx[y2];
                if (lastX.contains(y1) && lastX.contains(y2) && lastX[y1] == lastX[y2]) {
                    int prevX = lastX[y1];
                    int maxInside = st.query(1, 0, ys.size() - 1, idx1, idx2);
                    if (maxInside <= prevX) {
                        long long area = 1LL * (x - prevX) * (y2 - y1);
                        ans = max(ans, area);
                    }
                }
            }
            for (size_t k = i; k < j; ++k) {
                int x = points[k].first, y = points[k].second;
                int idx = yToIdx[y];
                lastX[y] = x;
                st.update(1, 0, ys.size() - 1, idx, x);
            }
            i = j;
        }
        return ans;
    }
};

class Solution {
    static class SegmentTree {
        int n;
        int[] tree;
        SegmentTree(int size) {
            n = size;
            tree = new int[4 * size];
            Arrays.fill(tree, -1);
        }
        void update(int node, int l, int r, int idx, int val) {
            if (l == r) { tree[node] = val; return; }
            int mid = (l + r) / 2;
            if (idx <= mid) update(2 * node, l, mid, idx, val);
            else update(2 * node + 1, mid + 1, r, idx, val);
            tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
        }
        int query(int node, int l, int r, int ql, int qr) {
            if (ql <= l && r <= qr) return tree[node];
            if (r < ql || l > qr) return -1;
            int mid = (l + r) / 2;
            return Math.max(query(2 * node, l, mid, ql, qr), query(2 * node + 1, mid + 1, r, ql, qr));
        }
    }

    public long maxRectangleArea(int[] xCoord, int[] yCoord) {
        int n = xCoord.length;
        int[][] points = new int[n][2];
        for (int i = 0; i < n; ++i) points[i] = new int[]{xCoord[i], yCoord[i]};
        Arrays.sort(points, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));

        int[] ys = Arrays.stream(yCoord).distinct().sorted().toArray();
        Map<Integer, Integer> yToIdx = new HashMap<>();
        for (int i = 0; i < ys.length; ++i) yToIdx.put(ys[i], i);

        SegmentTree st = new SegmentTree(ys.length);
        Map<Integer, Integer> lastX = new HashMap<>();
        long ans = -1;

        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && points[j][0] == points[i][0]) j++;
            for (int k = i; k + 1 < j; ++k) {
                int x = points[k][0], y1 = points[k][1], y2 = points[k + 1][1];
                int idx1 = yToIdx.get(y1), idx2 = yToIdx.get(y2);
                if (lastX.containsKey(y1) && lastX.containsKey(y2) && lastX.get(y1).equals(lastX.get(y2))) {
                    int prevX = lastX.get(y1);
                    int maxInside = st.query(1, 0, ys.length - 1, idx1, idx2);
                    if (maxInside <= prevX) {
                        long area = 1L * (x - prevX) * (y2 - y1);
                        ans = Math.max(ans, area);
                    }
                }
            }
            for (int k = i; k < j; ++k) {
                int x = points[k][0], y = points[k][1];
                int idx = yToIdx.get(y);
                lastX.put(y, x);
                st.update(1, 0, ys.length - 1, idx, x);
            }
            i = j;
        }
        return ans;
    }
}

var maxRectangleArea = function(xCoord, yCoord) {
    const n = xCoord.length;
    const points = Array.from({ length: n }, (_, i) => [xCoord[i], yCoord[i]]);
    points.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]);

    const ys = Array.from(new Set(yCoord)).sort((a, b) => a - b);
    const yToIdx = new Map(ys.map((y, i) => [y, i]));

    const tree = new Int32Array(4 * ys.length).fill(-1);
    const update = (node, l, r, idx, val) => {
        if (l === r) { tree[node] = val; return; }
        const mid = (l + r) >> 1;
        if (idx <= mid) update(2 * node, l, mid, idx, val);
        else update(2 * node + 1, mid + 1, r, idx, val);
        tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
    };
    const query = (node, l, r, ql, qr) => {
        if (ql <= l && r <= qr) return tree[node];
        if (r < ql || l > qr) return -1;
        const mid = (l + r) >> 1;
        return Math.max(query(2 * node, l, mid, ql, qr), query(2 * node + 1, mid + 1, r, ql, qr));
    };

    const lastX = new Map();
    let ans = -1;

    let i = 0;
    while (i < n) {
        let j = i;
        while (j < n && points[j][0] === points[i][0]) j++;
        for (let k = i; k + 1 < j; k++) {
            const x = points[k][0], y1 = points[k][1], y2 = points[k + 1][1];
            const idx1 = yToIdx.get(y1), idx2 = yToIdx.get(y2);
            if (lastX.has(y1) && lastX.has(y2) && lastX.get(y1) === lastX.get(y2)) {
                const prevX = lastX.get(y1);
                const maxInside = query(1, 0, ys.length - 1, idx1, idx2);
                if (maxInside <= prevX) {
                    const area = (x - prevX) * (y2 - y1);
                    if (area > ans) ans = area;
                }
            }
        }
        for (let k = i; k < j; k++) {
            const [x, y] = points[k];
            const idx = yToIdx.get(y);
            lastX.set(y, x);
            update(1, 0, ys.length - 1, idx, x);
        }
        i = j;
    }
    return ans;
};
